        AND FR.IND_ORIGEM = 'P'
        AND AP.IND_ATIVO = 'S'
) ATUAL ON ATUAL.COD_RUBRICA = ANTERIOR.COD_RUBRICA AND ATUAL.MATRICULA = ANTERIOR.MATRICULA AND ATUAL.ID_PENSIONISTA_PA = ANTERIOR.ID_PENSIONISTA_PA
