        JOIN SW_TVANTARES.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
        JOIN SW_TVANTARES.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
        JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
        JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FR.ID_RUBRICA
        JOIN SW_TVANTARES.FUNC_PEN_ALIM_PENSIONISTA AP ON AP.ID_PENSIONISTA_PA = FR.ID_PENSIONISTA_PA AND AP.DATA_FIM IS NULL
        JOIN SW_PUBLICO.PESSOA_DECLARACAO_FAMILIA PF ON PF.ID_DECLARACAO_FAMILIA = AP.ID_DECLARACAO_FAMILIA
        JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = PF.ID_PESSOA_DEPENDENTE AND HN.DATA_FIM IS NULL
    WHERE
        FO.MES = 8
        AND FO.ANO = 2026
        AND FR.IND_ORIGEM = 'P'
        AND AP.IND_ATIVO = 'S'
    ) ANTERIOR
    LEFT JOIN (
    SELECT
        'TVANTARES' ORGAO,
        FO.CHAVE_FOLHA,
        FF.COD_INSTITUCIONAL MATRICULA,
        R.COD_RUBRICA,
        R.NOME_RUBRICA RUBRICA,
        FR.VALOR_MULTIPLICADOR,
        FR.ID_PENSIONISTA_PA,
        HN.NOME,
        PS.NOME_SITUACAO,
        AP.DATA_INICIO,
        AP.DATA_FIM
    FROM
        SW_TVANTARES.FOLHA FO
        JOIN SW_TVANTARES.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
        JOIN SW_TVANTARES.FOLHA_FUNC_RUBRICA_IMPORTADA FR ON FR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
        JOIN SW_TVANTARES.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
        JOIN SW_TVANTARES.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
        JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
        JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FR.ID_RUBRICA
        JOIN SW_TVANTARES.FUNC_PEN_ALIM_PENSIONISTA AP ON AP.ID_PENSIONISTA_PA = FR.ID_PENSIONISTA_PA AND AP.DATA_FIM IS NULL
        JOIN SW_PUBLICO.PESSOA_DECLARACAO_FAMILIA PF ON PF.ID_DECLARACAO_FAMILIA = AP.ID_DECLARACAO_FAMILIA
        JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = PF.ID_PESSOA_DEPENDENTE AND HN.DATA_FIM IS NULL
    WHERE
        FO.MES = 9
        AND FO.ANO = 2026
        AND FR.IND_ORIGEM = 'P'
        AND AP.IND_ATIVO = 'S'
) ATUAL ON ATUAL.COD_RUBRICA = ANTERIOR.COD_RUBRICA AND ATUAL.MATRICULA = ANTERIOR.MATRICULA AND ATUAL.ID_PENSIONISTA_PA = ANTERIOR.ID_PENSIONISTA_PA
UNION ALL
SELECT
    ANTERIOR.ORGAO,
    ANTERIOR.CHAVE_FOLHA,
    ANTERIOR.MATRICULA,
    ANTERIOR.COD_RUBRICA,
    ANTERIOR.RUBRICA,
    ANTERIOR.VALOR_MULTIPLICADOR VALOR_AGOSTO,
    ATUAL.VALOR_MULTIPLICADOR VALOR_SETEMBRO,
    ANTERIOR.ID_PENSIONISTA_PA,
    ANTERIOR.NOME NOME_PENSIONISTA,
    ANTERIOR.NOME_SITUACAO SITUACAO_AGOSTO,
    ANTERIOR.NOME_SITUACAO SITUACAO_SETEMBRO,
    ANTERIOR.DATA_INICIO DATA_INICIO_AGOSTO,
    ANTERIOR.DATA_FIM DATA_FIM_AGOSTO,
    ATUAL.DATA_INICIO DATA_INICIO_SETEMBRO,
    ATUAL.DATA_FIM DATA_FIM_SETEMBRO
FROM
    (
    SELECT 
        'VICEGOV' ORGAO,
        FO.CHAVE_FOLHA,
        FF.COD_INSTITUCIONAL MATRICULA,
        R.COD_RUBRICA,
        R.NOME_RUBRICA RUBRICA,
        FR.VALOR_MULTIPLICADOR,
        FR.ID_PENSIONISTA_PA,
        HN.NOME,
        PS.NOME_SITUACAO,
        AP.DATA_INICIO,
        AP.DATA_FIM
    FROM
        SW_VICEGOV.FOLHA FO
        JOIN SW_VICEGOV.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
        JOIN SW_VICEGOV.FOLHA_FUNC_RUBRICA_IMPORTADA FR ON FR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
        JOIN SW_VICEGOV.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
        JOIN SW_VICEGOV.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
        JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
        JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FR.ID_RUBRICA
        JOIN SW_VICEGOV.FUNC_PEN_ALIM_PENSIONISTA AP ON AP.ID_PENSIONISTA_PA = FR.ID_PENSIONISTA_PA AND AP.DATA_FIM IS NULL
        JOIN SW_PUBLICO.PESSOA_DECLARACAO_FAMILIA PF ON PF.ID_DECLARACAO_FAMILIA = AP.ID_DECLARACAO_FAMILIA
        JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = PF.ID_PESSOA_DEPENDENTE AND HN.DATA_FIM IS NULL
    WHERE
        FO.MES = 8
        AND FO.ANO = 2026
        AND FR.IND_ORIGEM = 'P'
        AND AP.IND_ATIVO = 'S'
    ) ANTERIOR
    LEFT JOIN (
    SELECT
        'VICEGOV' ORGAO,
        FO.CHAVE_FOLHA,
        FF.COD_INSTITUCIONAL MATRICULA,
        R.COD_RUBRICA,
        R.NOME_RUBRICA RUBRICA,
        FR.VALOR_MULTIPLICADOR,
        FR.ID_PENSIONISTA_PA,
        HN.NOME,
        PS.NOME_SITUACAO,
        AP.DATA_INICIO,
        AP.DATA_FIM
    FROM
        SW_VICEGOV.FOLHA FO
        JOIN SW_VICEGOV.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
        JOIN SW_VICEGOV.FOLHA_FUNC_RUBRICA_IMPORTADA FR ON FR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
        JOIN SW_VICEGOV.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
        JOIN SW_VICEGOV.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
        JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
        JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FR.ID_RUBRICA
        JOIN SW_VICEGOV.FUNC_PEN_ALIM_PENSIONISTA AP ON AP.ID_PENSIONISTA_PA = FR.ID_PENSIONISTA_PA AND AP.DATA_FIM IS NULL
        JOIN SW_PUBLICO.PESSOA_DECLARACAO_FAMILIA PF ON PF.ID_DECLARACAO_FAMILIA = AP.ID_DECLARACAO_FAMILIA
        JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = PF.ID_PESSOA_DEPENDENTE AND HN.DATA_FIM IS NULL
    WHERE
        FO.MES = 9
        AND FO.ANO = 2026
        AND FR.IND_ORIGEM = 'P'
        AND AP.IND_ATIVO = 'S'
) ATUAL ON ATUAL.COD_RUBRICA = ANTERIOR.COD_RUBRICA AND ATUAL.MATRICULA = ANTERIOR.MATRICULA AND ATUAL.ID_PENSIONISTA_PA = ANTERIOR.ID_PENSIONISTA_PA
;